{"code": "def shift(c,sub=d):
    p=sub.pivot_table(index='date',columns=c,values='unblended_cost',aggfunc='sum').fillna(0)
    pre=p.loc['2025-04-27':'2025-05-10'];post=p.loc['2025-05-11':]
    r=pd.DataFrame({'pre_mean':pre.mean(),'pre_max':pre.max(),'post_min':post.min(),'post_mean':post.mean(),'first':p.apply(lambda s:s[s>0].index.min())})
    r['delta']=r.post_mean-r.pre_mean
    return r.sort_values('delta',ascending=False).head(8)
for c in ['application','instance_family']: print(shift(c))
