{"code": "import pandas as pd
df=pd.read_csv('data.csv')
d=df[df.account_id=='ylt9uT4'].copy();d['date']=pd.to_datetime(d['date'])
def score(c):
    p=d.pivot_table(index='date',columns=c,values='unblended_cost',aggfunc='sum').fillna(0)
    pre=p.loc['2025-03-25':'2025-04-07'];post=p.loc['2025-04-08':'2025-04-12']
    s=pd.DataFrame({'pre':pre.mean(),'prestd':pre.std(),'d0':p.loc['2025-04-08'],'post':post.mean(),'firstday':(p>0).idxmax()})
    s['diff']=s.post-s.pre; s['z']=s['diff']/s.prestd
    return s.sort_values('diff',ascending=False)
for c in ['application','instance_family']: print(score(c).head(10).round(1))
x=d[d.cloud_service=='3eLLM']
for c in ['application','instance_family']:
    p=x.pivot_table(index='date',columns=c,values='unblended_cost',aggfunc='sum').fillna(0)
    print(p.loc['2025-04-02':'2025-04-12'].round(0).T.to_string())"}

