{"code": "A=pd.Timestamp('2025-05-12')
for c in ['application','instance_family','cloud_service']:
    p=d.pivot_table(index=c,columns='date',values='unblended_cost',aggfunc='sum').fillna(0)
    cols=list(p.columns);i=cols.index(A)
    base=p[cols[i-14:i]].mean(axis=1); sd=p[cols[i-14:i]].std(axis=1)
    post=p[cols[i:i+7]].mean(axis=1); pw=p[cols[i-7:i]].mean(axis=1)
    r=pd.DataFrame({'base':base,'sd':sd,'d11':p[cols[i-1]],'d12':p[A],'post':post,'shift':post-base,'z':(post-base)/sd,'wk':p[A]-pw}).sort_values('shift')
    print(c);print(r.tail(8).round(1))
    if c=='application':print('new:',[x for x in p.index if p.loc[x,cols[:i]].sum()==0 and p.loc[x,A]>0])
    print(r.sort_values('wk').tail(3).round(1))"}

